import json, logging
from tenacity import retry, stop_after_attempt, wait_exponential_jitter, retry_if_exception_type

class TransientError(Exception): pass
class PermanentError(Exception): pass

@retry(retry=retry_if_exception_type(TransientError),
       stop=stop_after_attempt(4),
       wait=wait_exponential_jitter(initial=1, max=30),
       reraise=True)
def write_to_warehouse(record):
    resp = warehouse_client.upsert(record)        # idempotent upsert on record['id']
    if resp.status in (429, 503):
        raise TransientError(f"retryable {resp.status}")
    if resp.status >= 400:
        raise PermanentError(f"non-retryable {resp.status}")

def process_event(raw, dlq):
    try:
        record = json.loads(raw)                  # parse errors are permanent
    except json.JSONDecodeError as e:
        dlq.send(raw, reason=f"parse_error: {e}")
        return
    try:
        write_to_warehouse(record)
    except TransientError as e:
        dlq.send(raw, reason=f"retries_exhausted: {e}")  # gave up after backoff
    except PermanentError as e:
        dlq.send(raw, reason=f"permanent: {e}")
    except Exception as e:
        logging.exception("unexpected"); dlq.send(raw, reason=f"unexpected: {e}")
